package org.jsoup.nodes;

import java.io.*;
import java.io.Appendable;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Map;
import org.jsoup.SerializationException;
import org.jsoup.helper.Validate;
import org.jsoup.internal.StringUtil;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.junit.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertThrows;

@RunWith(JUnit4.class)
public class Attribute_setValue_TriageGen0Test {

    @Test
    public void testSetValue_NullVal() {
        Attribute attribute = new Attribute("key", null);
        attribute.setValue(null);
        assertNull(attribute.val);
        assertNull(attribute.parent.get(attribute.key));
    }

    @Test
    public void testSetValue_EmptyVal() {
        Attribute attribute = new Attribute("key", "");
        attribute.setValue("");
        assertEquals("", attribute.val);
        assertEquals("", attribute.parent.get(attribute.key));
    }

    @Test
    public void testSetValue_SomeVal() {
        Attribute attribute = new Attribute("key", "oldVal");
        attribute.setValue("newVal");
        assertEquals("newVal", attribute.val);
        assertEquals("newVal", attribute.parent.get(attribute.key));
    }

    @Test
    public void testSetValue_NullParent() {
        Attribute attribute = new Attribute("key", "oldVal");
        attribute.parent = null;
        attribute.setValue("newVal");
        assertEquals("newVal", attribute.val);
        assertEquals("newVal", attribute.parent.get(attribute.key));
    }

    @Test
    public void testSetValue_NullKey() {
        Attribute attribute = new Attribute(null, "oldVal");
        attribute.setValue("newVal");
        assertEquals("newVal", attribute.val);
        assertEquals("newVal", attribute.parent.get(attribute.key));
    }

    @Test
    public void testSetValue_KeyNotFound() {
        Attribute attribute = new Attribute("key", "oldVal");
        Attributes attributes = new Attributes();
        attribute.parent = attributes;
        attribute.setValue("newVal");
        assertEquals("newVal", attribute.val);
        assertEquals("newVal", attribute.parent.get(attribute.key));
    }

    @Test
    public void testSetValue_KeyFound() {
        Attribute attribute = new Attribute("key", "oldVal");
        Attributes attributes = new Attributes();
        attributes.vals = new String[] { "oldVal" };
        attribute.parent = attributes;
        attribute.setValue("newVal");
        assertEquals("newVal", attribute.val);
        assertEquals("newVal", attribute.parent.get(attribute.key));
    }

    @Test
    public void testSetValue_TooLongVal() {
        Attribute attribute = new Attribute("key", "oldVal");
        String val = new String(new char[1000]).replace('\0', 'a');
        attribute.setValue(val);
        assertEquals(val, attribute.val);
        assertEquals(val, attribute.parent.get(attribute.key));
    }

    @Test
    public void testSetValue_NullVal_ThrowsNpe() {
        Attribute attribute = new Attribute("key", null);
        assertThrows(NullPointerException.class, () -> attribute.setValue(null));
    }
}
